import React, { useState, useEffect } from 'react';
import { Bell, Trash2, Plus, AlertTriangle, Info, Calendar } from 'lucide-react';
import API from '../utils/api';

const Notices = ({ user }) => {
  const [notices, setNotices] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({ title: '', description: '', type: 'alert' });

  useEffect(() => {
    fetchNotices();
  }, []);

  const fetchNotices = async () => {
    try {
      const { data } = await API.get('/notices');
      setNotices(data);
    } catch (err) { console.error("Error loading notices"); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to remove this notice?")) return;
    try {
      await API.delete(`/notices/${id}`);
      fetchNotices();
    } catch (err) { alert("Failed to delete"); }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await API.post('/notices', formData);
      setShowForm(false);
      setFormData({ title: '', description: '', type: 'alert' });
      fetchNotices();
    } catch (err) { alert("Failed to post notice"); }
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6 animate-fade-in">

      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
          <Bell className="text-blue-600" /> Community Notices
        </h2>

        {user.role === 'admin' && (
          <button
            onClick={() => setShowForm(!showForm)}
            className="bg-slate-900 text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-slate-800 transition"
          >
            {showForm ? 'Cancel' : <><Plus size={18} /> New Notice</>}
          </button>
        )}
      </div>

      {/* CREATE FORM (Admin Only) */}
      {showForm && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="font-bold text-lg mb-4">Post New Announcement</h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="md:col-span-2">
                <label className="block text-sm font-bold text-slate-500 mb-1">Title</label>
                <input
                  type="text" required
                  className="w-full p-3 border rounded-xl"
                  value={formData.title}
                  onChange={e => setFormData({ ...formData, title: e.target.value })}
                  placeholder="e.g. Water Supply Interruption"
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-500 mb-1">Type</label>
                <select
                  className="w-full p-3 border rounded-xl bg-white"
                  value={formData.type}
                  onChange={e => setFormData({ ...formData, type: e.target.value })}
                >
                  <option value="alert">🚨 High Alert</option>
                  <option value="maintenance">🛠 Maintenance</option>
                  <option value="event">🎉 Event</option>
                </select>
              </div>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-500 mb-1">Description (Optional)</label>
              <textarea
                className="w-full p-3 border rounded-xl h-24"
                value={formData.description}
                onChange={e => setFormData({ ...formData, description: e.target.value })}
                placeholder="Provide detailed information..."
              />
            </div>
            <button className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-700">
              Post Notice
            </button>
          </form>
        </div>
      )}

      {/* NOTICE LIST */}
      <div className="grid gap-4">
        {notices.map((notice) => (
          <div key={notice.id} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition">
            <div className="flex justify-between items-start">
              <div className="flex gap-4">
                <div className={`p-3 rounded-xl h-fit ${notice.type === 'alert' ? 'bg-red-100 text-red-600' :
                    notice.type === 'maintenance' ? 'bg-blue-100 text-blue-600' : 'bg-amber-100 text-amber-600'
                  }`}>
                  {notice.type === 'alert' ? <AlertTriangle size={24} /> :
                    notice.type === 'maintenance' ? <Info size={24} /> : <Calendar size={24} />}
                </div>
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`text-xs font-bold uppercase px-2 py-0.5 rounded ${notice.type === 'alert' ? 'bg-red-50 text-red-600' :
                        notice.type === 'maintenance' ? 'bg-blue-50 text-blue-600' : 'bg-amber-50 text-amber-600'
                      }`}>
                      {notice.type}
                    </span>
                    <span className="text-xs text-slate-400">{new Date(notice.createdAt).toLocaleDateString('en-GB')}</span>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800">{notice.title}</h3>
                  <p className="text-slate-600 mt-2 leading-relaxed">{notice.description}</p>
                </div>
              </div>

              {user.role === 'admin' && (
                <button
                  onClick={() => handleDelete(notice.id)}
                  className="text-slate-400 hover:text-red-500 p-2 hover:bg-red-50 rounded-lg transition"
                  title="Delete Notice"
                >
                  <Trash2 size={18} />
                </button>
              )}
            </div>
          </div>
        ))}
        {notices.length === 0 && <p className="text-center text-slate-400 py-10">No notices found.</p>}
      </div>
    </div>
  );
};

export default Notices;

import React, { useState } from 'react';
import { User, Mail, MapPin, Save, Shield } from 'lucide-react';
import API from '../utils/api';

const Profile = ({ user, setUser }) => {
  const [formData, setFormData] = useState({
    name: user.name || '',
    email: user.email || '',
    wing: user.wing || '',
    flatNumber: user.flatNumber || ''
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const { data } = await API.put('/users/profile', formData);
      setUser(data); // Update global user state
      alert("✅ Profile Updated Successfully!");
    } catch (err) {
      alert("Failed to update profile.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6 animate-fade-in">
      <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
        <User className="text-blue-600" /> My Profile
      </h2>

      <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
        <div className="flex items-center gap-4 mb-8">
          <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center text-slate-400">
            <User size={32} />
          </div>
          <div>
            <h3 className="text-xl font-bold text-slate-800">{user.name}</h3>
            <span className="px-2 py-1 rounded text-xs font-bold bg-blue-50 text-blue-600 border border-blue-100 uppercase tracking-wider">
              {user.role}
            </span>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Full Name</label>
              <div className="relative">
                <User className="absolute left-3 top-3 text-slate-400" size={18} />
                <input 
                  name="name"
                  type="text" 
                  value={formData.name}
                  onChange={handleChange}
                  className="w-full pl-10 p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-3 top-3 text-slate-400" size={18} />
                <input 
                  name="email"
                  type="email" 
                  value={formData.email}
                  onChange={handleChange}
                  className="w-full pl-10 p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50 text-slate-500 cursor-not-allowed"
                  disabled // Usually better to disable email changing for security
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Wing</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 text-slate-400" size={18} />
                <input 
                  name="wing"
                  type="text" 
                  value={formData.wing}
                  onChange={handleChange}
                  className="w-full pl-10 p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Flat Number</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-3 text-slate-400" size={18} />
                <input 
                  name="flatNumber"
                  type="text" 
                  value={formData.flatNumber}
                  onChange={handleChange}
                  className="w-full pl-10 p-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>
          </div>

          <div className="pt-4 border-t border-slate-100 flex justify-end">
            <button 
              disabled={loading}
              className="bg-slate-900 text-white px-6 py-3 rounded-xl font-bold hover:bg-slate-800 transition flex items-center gap-2"
            >
              {loading ? 'Saving...' : <><Save size={18} /> Save Changes</>}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Profile;

import React, { useEffect, useState } from 'react';
import API from '../utils/api';
import { Building, Phone, MapPin, CheckCircle, Edit3, X } from 'lucide-react';

const SocietyShowcase = ({ user }) => {
    const [society, setSociety] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Edit Mode State
    const [isEditing, setIsEditing] = useState(false);
    const [formData, setFormData] = useState({});
    const [newAmenity, setNewAmenity] = useState('');

    const userRole = user?.role; // Use prop

    useEffect(() => {
        fetchSociety();
    }, []);

    const fetchSociety = async () => {
        try {
            const res = await API.get('/society');
            setSociety(res.data);
            setFormData(res.data);
        } catch (err) {
            setError('Failed to load society details.');
        } finally {
            setLoading(false);
        }
    };

    const handleUpdate = async () => {
        try {
            const data = new FormData();
            data.append('name', formData.name);
            data.append('address', formData.address);
            data.append('contactNumber', formData.contactNumber);
            data.append('amenities', JSON.stringify(formData.amenities));
            data.append('wings', JSON.stringify(formData.wings)); // Preserve wings if present

            if (formData.newGalleryFiles) {
                Array.from(formData.newGalleryFiles).forEach(file => {
                    data.append('gallery', file);
                });
            }

            if (formData.removeGalleryIndices) {
                data.append('removeGalleryIndices', JSON.stringify(formData.removeGalleryIndices));
            }

            // We need to set content-type for multipart, usually axios does it automatically if data is FormData
            const res = await API.put('/society', data, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });

            setSociety(res.data);
            setFormData(res.data); // Reset form data
            setIsEditing(false);
            alert('Society details updated!');
        } catch (err) {
            console.error(err);
            alert('Failed to update details.');
        }
    };

    const addAmenity = () => {
        if (newAmenity.trim()) {
            setFormData({
                ...formData,
                amenities: [...(formData.amenities || []), newAmenity]
            });
            setNewAmenity('');
        }
    };

    const removeAmenity = (index) => {
        const updated = [...formData.amenities];
        updated.splice(index, 1);
        setFormData({ ...formData, amenities: updated });
    };

    if (loading) return <div className="p-8 text-center text-slate-500">Loading society details...</div>;
    if (error) return <div className="p-8 text-center text-red-500">{error}</div>;

    return (
        <div className="p-6 md:p-10 space-y-8 animate-fade-in pb-24">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-slate-800">Society Showcase</h1>
                    <p className="text-slate-500">Overview of our community and facilities.</p>
                </div>
                {userRole === 'admin' && (
                    <button
                        onClick={() => setIsEditing(!isEditing)}
                        className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-lg hover:bg-slate-700 transition"
                    >
                        {isEditing ? <><X size={18} /> Cancel</> : <><Edit3 size={18} /> Edit Details</>}
                    </button>
                )}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Main Info Card */}
                <div className="lg:col-span-2 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-3xl p-8 text-white shadow-xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 rounded-full -translate-y-1/2 translate-x-1/4 blur-3xl"></div>

                    {isEditing ? (
                        <div className="space-y-4 text-slate-800">
                            <input
                                className="w-full p-3 rounded-lg"
                                value={formData.name || ''}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                placeholder="Society Name"
                            />
                            <textarea
                                className="w-full p-3 rounded-lg"
                                value={formData.address || ''}
                                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                                placeholder="Address"
                            />
                            <input
                                className="w-full p-3 rounded-lg"
                                value={formData.contactNumber || ''}
                                onChange={(e) => setFormData({ ...formData, contactNumber: e.target.value })}
                                placeholder="Contact Number"
                            />
                        </div>
                    ) : (
                        <>
                            <h2 className="text-4xl font-extrabold mb-4">{society.name}</h2>
                            <div className="space-y-4 text-blue-100">
                                <div className="flex items-start gap-3">
                                    <MapPin className="mt-1 flex-shrink-0" />
                                    <p className="text-lg leading-relaxed">{society.address || "Address not updated yet."}</p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <Phone />
                                    <p className="text-lg font-medium">{society.contactNumber || "No contact info."}</p>
                                </div>
                            </div>
                        </>
                    )}
                </div>

                {/* Amenities Card */}
                <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
                    <h3 className="text-xl font-bold text-slate-800 mb-6 flex items-center gap-2">
                        <Building className="text-rose-500" /> Amenities
                    </h3>

                    <div className="flex flex-wrap gap-3">
                        {isEditing ? (
                            <div className="w-full space-y-3">
                                <div className="flex gap-2">
                                    <input
                                        className="flex-1 p-2 border rounded-lg"
                                        placeholder="Add amenity..."
                                        value={newAmenity}
                                        onChange={(e) => setNewAmenity(e.target.value)}
                                    />
                                    <button onClick={addAmenity} className="bg-green-600 text-white px-3 rounded-lg">+</button>
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {formData.amenities && Array.isArray(formData.amenities) && formData.amenities.map((amenity, idx) => (
                                        <span key={idx} className="bg-slate-100 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                                            {amenity} <X size={14} className="cursor-pointer" onClick={() => removeAmenity(idx)} />
                                        </span>
                                    ))}
                                </div>
                            </div>
                        ) : (
                            society.amenities && Array.isArray(society.amenities) && society.amenities.length > 0 ? (
                                society.amenities.map((amenity, index) => (
                                    <span key={index} className="px-4 py-2 bg-rose-50 text-rose-600 rounded-full text-sm font-semibold flex items-center gap-2">
                                        <CheckCircle size={14} /> {amenity}
                                    </span>
                                ))
                            ) : (
                                <p className="text-slate-400 italic">No amenities listed.</p>
                            )
                        )}
                    </div>
                </div>
            </div>

            {/* Gallery Section */}
            <div className="mt-12">
                <h3 className="text-2xl font-bold text-slate-800 mb-6">Society Gallery</h3>
                {isEditing && (
                    <div className="mb-6 p-6 bg-slate-50 rounded-xl border border-dashed border-slate-300">
                        <p className="text-sm font-bold text-slate-500 mb-2">Upload New Photos</p>
                        <input
                            type="file"
                            multiple
                            onChange={(e) => {
                                const files = Array.from(e.target.files);
                                setFormData(prev => ({ ...prev, newGalleryFiles: files }));
                            }}
                            className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
                        />
                    </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
                    {society.gallery && society.gallery.length > 0 ? (
                        society.gallery.map((imgUrl, index) => (
                            <div key={index} className="relative group rounded-xl overflow-hidden shadow-md aspect-video">
                                <img src={imgUrl} alt={`Gallery ${index} `} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                                {isEditing && (
                                    <button
                                        onClick={() => {
                                            // Mark for deletion
                                            const currentRemoved = formData.removeGalleryIndices || [];
                                            setFormData(prev => ({
                                                ...prev,
                                                removeGalleryIndices: [...currentRemoved, index]
                                            }));
                                            // Visually hide or remove from current view for UX
                                            const tempGallery = [...society.gallery];
                                            tempGallery.splice(index, 1);
                                            setSociety(prev => ({ ...prev, gallery: tempGallery }));
                                        }}
                                        className="absolute top-2 right-2 bg-red-600 text-white p-1 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                        <X size={16} />
                                    </button>
                                )}
                            </div>
                        ))
                    ) : (
                        <p className="col-span-full text-center text-slate-400 italic py-10">No photos added yet.</p>
                    )}
                </div>
            </div>

            {isEditing && (
                <div className="flex justify-end">
                    <button
                        onClick={handleUpdate}
                        className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold hover:bg-blue-700 transition shadow-lg shadow-blue-200"
                    >
                        Save Changes
                    </button>
                </div>
            )}
        </div>
    );
};

export default SocietyShowcase;

